"""Expose original stateful v12 archive layout/recovery in the unchanged Cargo graph."""
from pathlib import Path
import argparse,ast,hashlib,json
SHA=lambda v:hashlib.sha256(v).hexdigest()
PINS={"Cargo.toml":"9d95c6f534a0a5cd1b21dde659ebe2ed02c0ba7d52d5bc792118ec32d615ff14","Cargo.lock":"b868d2529f17dfb78ba390e078eb281a98d9850e4eaa12245739fec43ec97823","src/mcp/runtime/request_audit.rs":"b5189f2923153ffa83d0b45a7cdf89873b0f17ebbe6ec1b174c05bab291d73da","src/mcp/runtime/request_archive_store.rs":"efecc499d8032f06230e5048dfe2daf65d74560ab171aed707c187653e511c48","src/mcp/runtime/request_archive_store_tests.rs":"95d6ebd4a7a8eede5f254b051a8447e98735cd38a9882248228e24574c7308a7"}
STORE_APPEND="\n// Qualification-only stateful forwarding to unchanged v12 layout methods.\npub(super) struct __HiaArchiveLayoutOriginal {\n    handles: std::collections::HashMap<u64, Archive>,\n}\nimpl __HiaArchiveLayoutOriginal {\n    pub(super) fn new() -> Self { Self { handles: Default::default() } }\n    fn snapshot(archive: &Archive) -> Result<serde_json::Value> {\n        let layout = archive.0.layout.get().map(|layout| serde_json::json!({\n            \"anchor\": &layout.anchor,\n            \"anchor_stamp\": layout.anchor_stamp,\n            \"held_root\": identity(&layout.root.metadata().unwrap()),\n            \"held_shards\": layout.shards.iter().map(|v| identity(&v.metadata().unwrap())).collect::<Vec<_>>()\n        }));\n        Ok(serde_json::json!({\n            \"root\":archive.0.root_identity, \"legacy\":archive.0.legacy_identity,\n            \"layout\":layout\n        }))\n    }\n    pub(super) fn step(&mut self, value:&serde_json::Value) -> serde_json::Value {\n        let mut checkpoints:Vec<serde_json::Value> = Vec::new();\n        let result = (|| -> Result<serde_json::Value> {\n            let operation = value[\"operation\"].as_str().unwrap();\n            let handle = value.get(\"handle\").and_then(|v|v.as_u64()).unwrap_or(0);\n            if operation == \"open\" {\n                if self.handles.contains_key(&handle) { bail!(\"qualification handle already present\"); }\n                let archive = super::open_archive(std::path::Path::new(value[\"root\"].as_str().unwrap()))?;\n                let snapshot = Self::snapshot(&archive)?;\n                self.handles.insert(handle,archive);\n                return Ok(snapshot);\n            }\n            if operation == \"drop\" {\n                return Ok(serde_json::json!({\"dropped\":self.handles.remove(&handle).is_some()}));\n            }\n            if operation == \"clone\" {\n                let target = value[\"target\"].as_u64().unwrap();\n                if self.handles.contains_key(&target) { bail!(\"qualification target already present\"); }\n                let cloned = self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?.try_clone()?;\n                let snapshot = Self::snapshot(&cloned)?;\n                self.handles.insert(target,cloned);\n                return Ok(snapshot);\n            }\n            let archive = self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n            match operation {\n                \"state\" => Self::snapshot(archive),\n                \"load\" => { archive.load_layout()?; Self::snapshot(archive) },\n                \"initialize\" => {\n                    let cut = value.get(\"cut\").and_then(|v|v.as_str());\n                    archive.initialize_with(&mut |step| {\n                        let text = match step {\n                            InitStep::Intent => \"Intent\".to_owned(),\n                            InitStep::RootCreated => \"RootCreated\".to_owned(),\n                            InitStep::RootBound => \"RootBound\".to_owned(),\n                            InitStep::ShardCreated(i) => format!(\"ShardCreated({i})\"),\n                            InitStep::ShardBound(i) => format!(\"ShardBound({i})\"),\n                            InitStep::Anchor => \"Anchor\".to_owned(),\n                            InitStep::IntentRemoved => \"IntentRemoved\".to_owned(),\n                        };\n                        checkpoints.push(serde_json::json!(text));\n                        if cut == Some(text.as_str()) { bail!(\"injected initialization interruption\"); }\n                        Ok(())\n                    })?;\n                    Self::snapshot(archive)\n                },\n                \"exclusive\" => Ok(serde_json::json!({\"exclusive\":archive.needs_exclusive_open()?})),\n                \"fence\" => {\n                    if let Some(path) = value.get(\"root\").and_then(|v|v.as_str()) {\n                        let root = File::open(path)?;\n                        archive.fence_at(&root)?;\n                    } else { archive.fence_at(archive.root())?; }\n                    Ok(serde_json::json!({\"fenced\":true}))\n                },\n                \"full_layout\" => {\n                    if let Some(layout) = archive.0.layout.get() { archive.validate_layout(layout,true)?; }\n                    Ok(serde_json::json!({\"validated\":true}))\n                },\n                \"directory_for_existing\" => {\n                    let directory = archive.directory_for_existing(value[\"filename\"].as_str().unwrap())?;\n                    Ok(serde_json::json!({\"identity\":identity(&directory.metadata()?)}))\n                },\n                \"directory_for_write\" => {\n                    let directory = archive.directory_for_write(value[\"filename\"].as_str().unwrap(),value[\"replacing\"].as_bool().unwrap())?;\n                    Ok(serde_json::json!({\"identity\":identity(&directory.metadata()?)}))\n                },\n                \"fence_record\" | \"fence_target\" => {\n                    let directory = if value[\"target\"] == \"legacy\" { archive.legacy() } else {\n                        let index=value[\"target\"].as_u64().unwrap() as usize;\n                        let layout=archive.0.layout.get().ok_or_else(||anyhow!(\"qualification no layout\"))?;\n                        layout.shards.get(index).ok_or_else(||anyhow!(\"qualification shard out of range\"))?.as_ref()\n                    };\n                    if operation==\"fence_record\" { archive.fence_record(value[\"filename\"].as_str().unwrap(),directory)?; }\n                    else { archive.fence_target(directory)?; }\n                    Ok(serde_json::json!({\"fenced\":true}))\n                },\n                \"walk\" | \"physical_walk\" => {\n                    let mut entries=Vec::new();\n                    let mut visit=|directory:&File,filename:&str,inode:u64|->Result<()> {\n                        entries.push(serde_json::json!({\"directory\":identity(&directory.metadata()?),\"filename\":filename,\"inode\":inode}));\n                        Ok(())\n                    };\n                    if operation==\"walk\" { archive.walk(&mut visit)?; }\n                    else { archive.walk_for_complete_identity_join(&mut visit)?; }\n                    Ok(serde_json::json!({\"entries\":entries}))\n                },\n                \"save\" => {\n                    let record:Record=serde_json::from_value(value[\"record\"].clone())?;\n                    save_archive_with_sync(archive,&record,value[\"replacing\"].as_bool().unwrap(),value[\"sync\"].as_bool().unwrap())?;\n                    Ok(serde_json::json!({\"saved\":true}))\n                },\n                \"read_record\" => Ok(serde_json::to_value(archive.read_record(value[\"filename\"].as_str().unwrap())?)?),\n                \"content_version\" => Ok(serde_json::json!({\"version\":format!(\"{:?}\",archive.content_version()?)})),\n                _ => bail!(\"unknown qualification operation\"),\n            }\n        })();\n        match result {\n            Ok(value)=>serde_json::json!({\"accepted\":true,\"value\":value,\"checkpoints\":checkpoints}),\n            Err(error)=>serde_json::json!({\"accepted\":false,\"error\":{\n                \"text\":format!(\"{error:#}\"),\n                \"io_errno\":error.downcast_ref::<std::io::Error>().and_then(std::io::Error::raw_os_error),\n                \"io_kind\":error.downcast_ref::<std::io::Error>().map(|v|format!(\"{:?}\",v.kind()))\n            },\"checkpoints\":checkpoints})\n        }\n    }\n}\n"
AUDIT_APPEND="\n// Qualification-only opaque state; no replacement of original archive policy.\n#[doc(hidden)]\npub struct __HiaDurableArchiveLayoutOriginal(archive_store::__HiaArchiveLayoutOriginal);\nimpl __HiaDurableArchiveLayoutOriginal {\n    pub fn new() -> Self { Self(archive_store::__HiaArchiveLayoutOriginal::new()) }\n    pub fn step(&mut self,value:&serde_json::Value)->serde_json::Value { self.0.step(value) }\n}\n"
BIN="use std::io::{BufRead,Write};\nfn main()->std::io::Result<()> {\n let mut state=hepta_runtime::mcp::runtime::request_audit::__HiaDurableArchiveLayoutOriginal::new();\n let mut output=std::io::stdout().lock();\n for line in std::io::stdin().lock().lines() {\n  let value:serde_json::Value=serde_json::from_str(&line?).unwrap();\n  let result=state.step(&value);\n  writeln!(output,\"{}\",serde_json::to_string(&result).unwrap())?;output.flush()?;\n }\n Ok(())\n}\n"

def literals(path,pin):
 raw=path.read_bytes();assert SHA(raw)==pin
 return {t.id:ast.literal_eval(n.value)for n in ast.parse(raw).body if isinstance(n,ast.Assign)for t in n.targets if isinstance(t,ast.Name)and t.id in{"APPEND","STORE_APPEND","AUDIT_APPEND","BIN"}}
def main():
 p=argparse.ArgumentParser();p.add_argument("--project",type=Path,required=True);p.add_argument("--history-preparer",type=Path,required=True);p.add_argument("--records-preparer",type=Path,required=True);p.add_argument("--anchor-preparer",type=Path,required=True);p.add_argument("--metadata-preparer",type=Path,required=True);a=p.parse_args();root=a.project
 history=literals(a.history_preparer,"844713331bb1b0ea0713cfc57622f0f363767f38dcb986b408c2d01cf35892ae")
 records=literals(a.records_preparer,"f94091c91999da81d28178a79697aa87a0f7453bf8b3c0aa6bd145773bf2277a")
 anchor=literals(a.anchor_preparer,"5ce30c05fa506c822ad96ec3a6cb4f275c62bd9ab9bf63d7fee6e33f3f9ac0d5")
 metadata=literals(a.metadata_preparer,"9e4d9bdb33ed226423aa35166c310ebec6ae83620ba4f1f87c62439bdbd660b1")
 originals={n:(root/"audit_current_history"/("original-"+n.replace("/","__"))).read_bytes()for n in list(PINS)[:3]}
 originals["src/mcp/runtime/request_archive_store.rs"]=(root/"audit_archive_records/before-src__mcp__runtime__request_archive_store.rs").read_bytes()
 originals["src/mcp/runtime/request_archive_store_tests.rs"]=(root/"src/mcp/runtime/request_archive_store_tests.rs").read_bytes()
 for n,v in originals.items():assert SHA(v)==PINS[n],n
 expected=dict(originals)
 for name,path in[("hia-durable-audit-history-original","audit_current_history/oracle.rs"),("hia-durable-archive-records-original","audit_archive_records/oracle.rs"),("hia-durable-archive-anchor-original","audit_anchor_fs/oracle.rs"),("hia-durable-archive-metadata-original","audit_archive_metadata/oracle.rs")]:
  expected["Cargo.toml"]+=("\n[[bin]]\nname = "+json.dumps(name)+"\npath = "+json.dumps(path)+"\n").encode()
 expected["src/mcp/runtime/request_audit.rs"]+=history["APPEND"].encode()+records["AUDIT_APPEND"].encode()+anchor["AUDIT_APPEND"].encode()+metadata["AUDIT_APPEND"].encode()
 expected["src/mcp/runtime/request_archive_store.rs"]+=records["STORE_APPEND"].encode()+anchor["STORE_APPEND"].encode()+metadata["STORE_APPEND"].encode()
 before={n:(root/n).read_bytes()for n in PINS};assert before==expected
 q=root/"audit_archive_layout";q.mkdir(exist_ok=False)
 for n,v in before.items():(q/("before-"+n.replace("/","__"))).write_bytes(v)
 (q/"oracle.rs").write_text(BIN)
 for n,v in[("src/mcp/runtime/request_audit.rs",AUDIT_APPEND),("src/mcp/runtime/request_archive_store.rs",STORE_APPEND)]:
  with(root/n).open("ab")as f:f.write(v.encode())
 with(root/"Cargo.toml").open("ab")as f:f.write(b'\n[[bin]]\nname = "hia-durable-archive-layout-original"\npath = "audit_archive_layout/oracle.rs"\n')
 for n,v in before.items():assert(root/n).read_bytes().startswith(v),n
 assert(root/"Cargo.lock").read_bytes()==originals["Cargo.lock"]and(root/"src/mcp/runtime/request_archive_store_tests.rs").read_bytes()==originals["src/mcp/runtime/request_archive_store_tests.rs"]
 report=dict(schema="hepta.runtime.durable-archive-layout-original.v1",original_commit="abc9ecb95ee9538518ec3f36c47b881974107021",original=PINS,
 before={n:dict(bytes=len(v),sha256=SHA(v))for n,v in before.items()},after={n:dict(bytes=len(v),sha256=SHA(v))for n in PINS for v in[(root/n).read_bytes()]},
 original_functions_whole_bytes_preserved=True,original_tests_whole_bytes_preserved=True,graph_profile_default_features_unchanged=True,
 append_sha256={"audit":SHA(AUDIT_APPEND.encode()),"store":SHA(STORE_APPEND.encode()),"bin":SHA(BIN.encode())},
 scope="stateful original Archive open/load/initialize/fence/selection/walk only; checkpoint injection uses original callback; no method-body/lock/dependency/profile changes or native/public claim")
 (q/"source-relation.json").write_text(json.dumps(report,sort_keys=True,indent=2)+"\n");print(json.dumps(report,sort_keys=True),flush=True)
if __name__=="__main__":main()
